import sys
from collections import defaultdict, deque

def has_cycle_directed(n, m, edges):
    # Build adjacency list
    adj = defaultdict(list)
    indegree = [0] * (n + 1)

    for u, v in edges:
        adj[u].append(v)
        indegree[v] += 1

    # Kahn's algorithm
    q = deque()
    for i in range(1, n + 1):
        if indegree[i] == 0:
            q.append(i)

    count = 0
    while q:
        node = q.popleft()
        count += 1
        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                q.append(neighbor)

    return "Yes" if count < n else "No"

def main():
    data = sys.stdin.read().split()
    idx = 0
    results = []

    while idx < len(data):
        try:
            n = int(data[idx])
            m = int(data[idx + 1])
            idx += 2
        except (IndexError, ValueError):
            break

        if n < 0 or m < 0:
            break

        edges = []
        for _ in range(m):
            if idx + 1 >= len(data):
                break
            u = int(data[idx])
            v = int(data[idx + 1])
            idx += 2
            edges.append((u, v))

        results.append(has_cycle_directed(n, m, edges))

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
